/** Truncate s to at most n chars, appending '...' when cut. n counts the ellipsis. */
function truncate(s, n) {
  if (typeof s !== 'string') throw new TypeError('truncate: expected string');
  if (!Number.isInteger(n) || n < 3) throw new RangeError('truncate: n must be integer >= 3');
  if (s.length <= n) return s;
  return s.slice(0, n - 3) + '...';
}

/** Convert text to a URL slug: lowercase, ASCII-ish, hyphen-separated. */
function slugify(s) {
  if (typeof s !== 'string') throw new TypeError('slugify: expected string');
  return s
    .toLowerCase()
    .replace(/['"]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

