function csvRow(values) {
  if (!Array.isArray(values)) throw new TypeError('csvRow: expected array');
  return values
    .map((v) => {
      const str = String(v);
      if (/[",\n]/.test(str)) return '"' + str.replace(/"/g, '""') + '"';
      return str;
    })
    .join(',');
}

/** Capitalize first letter; leave rest untouched. Empty string stays empty. */
function capitalize(s) {
  if (typeof s !== 'string') throw new TypeError('capitalize: expected string');
  if (s.length === 0) return s;
  return s[0].toUpperCase() + s.slice(1);
}

/** Count non-overlapping occurrences of needle in haystack. */
function countOccurrences(haystack, needle) {
  if (typeof haystack !== 'string' || typeof needle !== 'string') {
    throw new TypeError('countOccurrences: expected strings');
