'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const { truncate, slugify, csvRow, capitalize, countOccurrences } = require('../lib/strings');

test('truncate keeps short strings untouched', () => {
  assert.equal(truncate('hello', 10), 'hello');
});

test('truncate cuts long strings and appends ellipsis within budget', () => {
  assert.equal(truncate('hello world', 8), 'hello...');
  assert.equal(truncate('hello world', 8).length, 8);
});

test('truncate at exact length returns original', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('truncate rejects n < 3 or non-integer', () => {
  assert.throws(() => truncate('x', 2), RangeError);
  assert.throws(() => truncate('x', 3.5), RangeError);
});

test('slugify lowercases and hyphenates', () => {
  assert.equal(slugify('Hello World'), 'hello-world');
});

test('slugify collapses repeated separators and trims edges', () => {
  assert.equal(slugify('  --Multiple   Spaces-- '), 'multiple-spaces');
});

test('slugify drops quotes', () => {
  assert.equal(slugify("It's a Test"), 'its-a-test');
});

test('csvRow joins plain values with commas', () => {
  assert.equal(csvRow([1, 'a', true]), '1,a,true');
});

test('csvRow quotes fields containing commas, quotes, newlines', () => {
  assert.equal(csvRow(['a,b', 'say "hi"', 'line\nbreak']), '"a,b","say ""hi""","line\nbreak"');
});

test('capitalize uppercases only the first char', () => {
  assert.equal(capitalize('hello'), 'Hello');
  assert.equal(capitalize('wORLD'), 'WORLD');
  assert.equal(capitalize(''), '');
});

test('countOccurrences counts non-overlapping matches', () => {
  assert.equal(countOccurrences('aaa', 'aa'), 1);
  assert.equal(countOccurrences('ababab', 'ab'), 3);
  assert.equal(countOccurrences('xyz', 'q'), 0);
});

test('countOccurrences rejects empty needle', () => {
  assert.throws(() => countOccurrences('abc', ''), RangeError);
});

