'use strict';

// Small numeric-statistics helpers for the demo fixture.

function assertNumbers(xs) {
  if (!Array.isArray(xs) || xs.length === 0) throw new RangeError('expected non-empty number array');
  if (xs.some((x) => typeof x !== 'number' || !Number.isFinite(x))) {
    throw new TypeError('all values must be finite numbers');
  }
}

/** Arithmetic mean. */
function mean(xs) {
  assertNumbers(xs);
  return xs.reduce((a, b) => a + b, 0) / xs.length;
}

/** Median; even-length arrays average the two middle values. */
function median(xs) {
  assertNumbers(xs);
  const sorted = [...xs].sort((a, b) => a - b);
  const mid = sorted.length >> 1;
  if (sorted.length % 2 === 1) return sorted[mid];
  return (sorted[mid - 1] + sorted[mid]) / 2;
}

/** Population variance. */
function variance(xs) {
  assertNumbers(xs);
  const m = mean(xs);
  return xs.reduce((acc, x) => acc + (x - m) ** 2, 0) / xs.length;
}

/** Population standard deviation. */
function stdev(xs) {
  return Math.sqrt(variance(xs));
}

/** Min-max normalize to [0,1]; constant arrays map to all zeros. */
function normalize(xs) {
  assertNumbers(xs);
  const min = Math.min(...xs);
  const max = Math.max(...xs);
  if (min === max) return xs.map(() => 0);
  const range = max - min;
  return xs.map((x) => (x - min) / range);
}

/** Linear percentile (0-100) via nearest-rank on sorted data. */
function percentile(xs, p) {
  assertNumbers(xs);
  if (!Number.isFinite(p) || p < 0 || p > 100) throw new RangeError('p must be within [0,100]');
  const sorted = [...xs].sort((a, b) => a - b);
  const rank = Math.ceil((p / 100) * sorted.length);
  return sorted[Math.max(rank, 1) - 1];
}

module.exports = { mean, median, variance, stdev, normalize, percentile };

